import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Task plan and approval gates","description":"The live team board holds assigned cards, actual status, editable dates, and named history.\\nThis page explains the dependency plan; it is not a second task tracker.\\nThe GDD de","frontmatter":{"title":"Task plan and approval gates","description":"The live team board holds assigned cards, actual status, editable dates, and named history.\\nThis page explains the dependency plan; it is not a second task tracker.\\nThe GDD de","source":"docs/kanban-plan-draft.md","category":"Delivery & team","sourceUpdated":"2026-11-11T13:03:58+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/kanban-plan-draft.md","filePath":"content/docs/kanban-plan-draft.md"}'),i={name:"content/docs/kanban-plan-draft.md"};function d(s,e,o,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r(`<div><h1 id="task-plan-and-approval-gates">Task plan and approval gates<a class="header-anchor" href="#task-plan-and-approval-gates" aria-label="Link to this section">​</a></h1><p>The <a href="https://owenlim225.github.io/Chainy-Docs/board/">live team board</a> holds assigned cards, actual status, editable dates, and named history. This page explains the dependency plan; it is not a second task tracker. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">GDD</a> defines 39 ordered lessons, nine distinct minigames, and 13 required correction-based questions per world. <strong>Documentation and preparation are authorized. Unity work waits for the owner&#39;s explicit final decision.</strong><strong>Pre-final remains November 21, 2026.</strong></p><h2 id="reconciliation-rules">Reconciliation rules<a class="header-anchor" href="#reconciliation-rules" aria-label="Link to this section">​</a></h2><p>The owner requested a smaller board and authorized recoverable archiving of obsolete work on November 11. Teacher services, vouchers, dashboards, exports, standalone Wordle/BlockMatch, economy purchases, restoration progression, and actual AI training are outside this delivery scope. Archive those cards rather than deleting them or marking them completed. Consolidate repetitive component checks and tiny art/UI tasks into deliverable cards whose acceptance preserves the necessary checks. Keep old IDs, audit history, evidence, and completed work. Retained In Progress states describe existing board history; they do not override the development hold.</p><p>The pre-change backup contains 108 active cards, five In Progress and three Done. The completed reconciliation retains 30 existing cards, adds six necessary cards, and archives 78 superseded cards, leaving 36 active deliverables. Owners and earlier evidence are preserved; direct status changes made on the board during the review remain intact. The final ID set, dependencies and conditional date order were verified against the private backup. The original <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/kanban-plan-draft.html">V2 schedule</a> remains available as history.</p><h2 id="deliverables-and-handoffs">Deliverables and handoffs<a class="header-anchor" href="#deliverables-and-handoffs" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Workstream</th><th>Owner</th><th>Concrete output and next handoff</th></tr></thead><tbody><tr><td>Design review and authorization</td><td>Sherwin</td><td>Review the complete design, then record a separate explicit decision to start Unity work</td></tr><tr><td>Documentation and learning content</td><td>Sean</td><td>One GDD, 39 sourced lesson panels, 39 questions with feedback, nine activity instructions, navigation, and publication checks; hand reviewed content to Christian and Miguel</td></tr><tr><td>Technical preparation</td><td>Christian</td><td>Document contracts and audited facts; after final approval establish a reproducible baseline before changing systems</td></tr><tr><td>Progress and game rules</td><td>Christian</td><td>Ordered lessons, SQLite checkpoints, three required reviews, separate activity scenes and nine verified success rules</td></tr><tr><td>Art handoff</td><td>Luis</td><td>Reusable player/guide/world kit plus lesson and activity props; deliver approved assets and specifications to Christian/Miguel</td></tr><tr><td>UI handoff</td><td>Miguel</td><td>Main/world/profile navigation, joystick and interaction states, encyclopedia, quests, dialogue, review, activity feedback, pause and save recovery</td></tr><tr><td>Integration and Android evidence</td><td>Christian</td><td>Integrate accepted outputs sequentially; demonstrate all three worlds, failures, retries, relaunch and two-profile isolation on a named Android build</td></tr><tr><td>Capstone evidence</td><td>Sean</td><td>Actual school requirements, approved evaluation protocol, honest result tables, manuscript and demonstration/handover pack</td></tr><tr><td>Readiness and rehearsal</td><td>Sherwin</td><td>Accept or reject the candidate from evidence, then rehearse the supported demonstration and recovery</td></tr></tbody></table><p>Each card has exactly one owner and one lane. Dependencies make the cross-role handoff explicit; agents do not become owners or shared-account identities. The completed main-character asset remains completed; new requirements do not erase that work.</p><h2 id="conditional-planning-windows">Conditional planning windows<a class="header-anchor" href="#conditional-planning-windows" aria-label="Link to this section">​</a></h2><p>The owner requested rebaselining unfinished work after documentation review. These are planning targets for review, not effort estimates, delivery guarantees, or authorization to start. They assume final design and development approval by November 12; if that does not happen, revise the forecast at the gate. No evidence yet proves that all nine games can be implemented and accepted in this interval. Preserve the required design, record delivery risk honestly, and protect QA and rehearsal rather than silently shrinking either.</p><table><thead><tr><th>Window</th><th>Gate or work</th></tr></thead><tbody><tr><td>November 11–12</td><td>Complete documentation, content and contract review; reconcile board and publishing setup</td></tr><tr><td>November 12</td><td>Owner design review and separate final development decision</td></tr><tr><td>November 13</td><td>After approval only: actual source/toolchain baseline and first failing checks</td></tr><tr><td>November 13–16</td><td>Conditional parallel progress, activity rules, art and UI packets with frozen handoffs</td></tr><tr><td>November 17–18</td><td>Sequential shared integration and full journey checks</td></tr><tr><td>November 18–19</td><td>Android/offline/recovery and UI acceptance; retest failures</td></tr><tr><td>November 19–20</td><td>Evidence consistency, manuscript, release candidate and readiness decision</td></tr><tr><td>November 20</td><td>Demonstration and recovery rehearsal</td></tr><tr><td><strong>November 21</strong></td><td><strong>Pre-final using only verified behavior and honest limitations</strong></td></tr><tr><td>November 22–27</td><td>Record actual panel feedback and revise remaining approved work; no speculative feature expansion</td></tr></tbody></table><p>The November 10 community session is a past scheduled event, not a future milestone or verified beta result. Record what actually happened and which evidence is permitted before using it in the manuscript. School requirements and any completion percentage must come from school guidance, never card counts.</p><h2 id="dependency-chain">Dependency chain<a class="header-anchor" href="#dependency-chain" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  Content[Reviewed lesson and activity content] --&gt; GDD[Complete documentation package]
  Contract[Documented system and data contracts] --&gt; GDD
  GDD --&gt; Review[Owner design review]
  Review --&gt; Approval[Explicit final development approval]
  Approval --&gt; Baseline[Source and toolchain baseline]
  Baseline --&gt; Progress[Progress and SQLite]
  Baseline --&gt; Games[Nine activity rules]
  Approval --&gt; Art[Art handoff]
  Progress --&gt; UI[UI and encounter integration]
  Games --&gt; UI
  Art --&gt; UI
  UI --&gt; Integration[Sequential integration]
  Integration --&gt; QA[Android and usability acceptance]
  QA --&gt; Readiness[Readiness decision and rehearsal]
  School[School requirements and permissions] --&gt; Evidence[Actual evidence and manuscript]
  Evidence --&gt; Readiness
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>The <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">readiness plan</a> defines future agent boundaries and proof requirements. No implementation worker, build, environment repair, or Unity inspection runs before the final approval gate.</p></div>`,1)])])}const v=t(i,[["render",d]]);export{u as __pageData,v as default};
